// Alpine.js CDN loader - downloads the real library at runtime
// This avoids bundling issues and ensures the latest compatible version loads
(function() {
    var script = document.createElement('script');
    script.src = 'https://cdn.jsdelivr.net/npm/alpinejs@3.14.3/dist/cdn.min.js';
    script.defer = true;
    document.head.appendChild(script);
})();
